def keys(payload):
    return sorted(payload['config'])

from copy import deepcopy

def resolve(payload):
    def overlay(old,new):
        out=deepcopy(old)
        for key,value in new.items():
            if value is None:out.pop(key,None)
            elif isinstance(value,dict):out[key]=overlay(out[key] if isinstance(out.get(key),dict) else {},value)
            else:out[key]=deepcopy(value)
        return out
    out=deepcopy(payload['defaults'])
    for layer in payload['layers']:out=overlay(out,layer)
    if any(key not in out for key in payload['required']):raise ValueError('missing required')
    return out

